package dev.risingheroes.core;

import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;

class AdditionalQuirksTest {
    private HeroProfile kit(String id){var p=new HeroProfile();HeroRules.assign(p,id);return p;}
    @Test void shadeUsesBrightnessAndFiniteRecovery(){var p=kit("umbrakinesis");HeroRules.reserveCast(p,0,100,false,false,false);assertEquals(87.5,QuirkResources.primary(p));p.resources.put("ambient_light",0.0);QuirkResources.recover(p);assertEquals(87.74,QuirkResources.primary(p),1e-6);QuirkResources.reserve(p,Catalog.move("shadow_lash"),200);assertEquals(77.74,QuirkResources.primary(p),1e-6);p.resources.put("shade",9.0);assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,500,false,false,false));}
    @Test void blueflameCannotExceedHeatOrCastFireUnderwater(){var p=kit("blueflame");p.resources.put("heat",90.0);assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,false,false));assertEquals(100,p.stamina);p.resources.put("heat",0.0);assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,false,true));assertDoesNotThrow(()->HeroRules.reserveCast(p,4,100,false,false,true));}
    @Test void kineticHasNoFreeChargeAndItsJabWorksAtZero(){var p=kit("kinetic_reservoir");for(int i=0;i<1000;i++)QuirkResources.recover(p);assertEquals(0,QuirkResources.primary(p));HeroRules.reserveCast(p,1,100,false,false,false);assertEquals(0,QuirkResources.primary(p));HeroRules.testingLoadout(p);p.slots.set(0,"counter_release");assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,1000,false,false,false));p.resources.put("impact",25.0);HeroRules.reserveCast(p,0,1000,false,false,false);assertEquals(5,QuirkResources.primary(p));}
    @Test void blockedImpactIsCappedAndGuardFatigueBreaksItsWindow(){var result=ImpactStorage.block("absorb_brace",8,0,8);assertEquals(6.4,result.remaining(),1e-5);assertEquals(3.2,result.stored(),1e-5);assertFalse(result.broken());var heavy=ImpactStorage.block("kinetic_bulwark",100,58,99);assertEquals(60,heavy.stored());assertEquals(100,heavy.fatigue());assertTrue(heavy.broken());assertThrows(IllegalArgumentException.class,()->ImpactStorage.block("absorb_brace",Float.NaN,0,0));assertThrows(IllegalArgumentException.class,()->ImpactStorage.block("unknown",8,0,0));}
    @Test void originalSourcesNeverInventOfficialWieldersOrContinuity(){for(String id:List.of("umbrakinesis","kinetic_reservoir")){var lore=QuirkLore.get(id);assertTrue(lore.sourceMedium().contains("Mod-original"));assertTrue(lore.continuity().contains("non-canon"));assertTrue(lore.references().isEmpty());assertTrue(lore.knownUsers().getFirst().contains("No official wielder"));}assertEquals("Main-series anime",QuirkLore.get("blueflame").sourceMedium());}
    @ParameterizedTest @ValueSource(strings={"blueflame","umbrakinesis","kinetic_reservoir"})
    void soloIndependentPracticeUnlocksTheCompleteKitWithoutCurrencyDuplication(String id){var p=kit(id);p.schoolStage=4;for(var mission:MissionCatalog.all())if(mission.path().equals("independent")){MissionRules.start(p,mission.id(),100);while(!p.mission.completed){var s=MissionRules.stage(p);for(int i=0;i<s.count();i++)MissionRules.witness(p,p.mission.session,s.type(),s.role(),s.id()+i);}MissionRules.leave(p);}assertTrue(p.currentUnlocks().containsAll(Kits.get(id).moves()));int credits=p.credits,mastery=p.mastery();MissionRules.start(p,"neighbourhood_watch",100);while(!p.mission.completed){var s=MissionRules.stage(p);for(int i=0;i<s.count();i++)MissionRules.witness(p,p.mission.session,s.type(),s.role(),s.id()+i);}assertEquals(credits,p.credits);assertEquals(mastery,p.mastery());}
}
